// startup regressions use the existing fake session
func TestInvalidPlan(t *testing.T) { resetCreated(t); assertRejected(t, invalidPlan()) }
func TestStartupClose(t *testing.T) { resetCreated(t); assertClosed(t, mismatchedPlan()) }
